import{_ as e,o as n,c as a,ak as o}from"./chunks/framework.B-uOQMuY.js";const i="/projects/ESP32-S3/en/latest/assets/image2.DXCLTllj.webp",r="/projects/ESP32-S3/en/latest/assets/1.D1vuJUQJ.webp",s="/projects/ESP32-S3/en/latest/assets/2.CRu2FsIV.webp",l="/projects/ESP32-S3/en/latest/assets/3.DHgcNrhV.webp",c="/projects/ESP32-S3/en/latest/assets/4.BFmVyhPm.webp",d="/projects/ESP32-S3/en/latest/assets/image2.DvWOSCpq.webp",p="/projects/ESP32-S3/en/latest/assets/image3.DMKHiJHU.webp",g="/projects/ESP32-S3/en/latest/assets/image4.BzpcPlKb.webp",h="data:image/png;base64,",m="/projects/ESP32-S3/en/latest/assets/image6.BuUbagPQ.webp",_=JSON.parse('{"title":"1. Product Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1.product_introduction.md","filePath":"docs/1.product_introduction.md"}'),u={name:"docs/1.product_introduction.md"};function y(x,t,w,f,A,S){return n(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-product-introduction" tabindex="-1">1. Product Introduction <a class="header-anchor" href="#_1-product-introduction" aria-label="Permalink to &quot;1. Product Introduction&quot;">​</a></h1><h2 id="_1-1-introduction-to-esp32-s3-vision-module" tabindex="-1">1.1 Introduction to ESP32-S3 Vision Module <a class="header-anchor" href="#_1-1-introduction-to-esp32-s3-vision-module" aria-label="Permalink to &quot;1.1 Introduction to ESP32-S3 Vision Module&quot;">​</a></h2><p><strong>1.1.1 Introduction &amp; Working Principle</strong></p><p>The ESP32-S3 vision module is a compact camera module that can operate as a minimal standalone system.</p><p>It captures images using a built-in camera module, processes the image data with an ESP32 microcontroller, and transmits the data wirelessly via a Wi-Fi module. Supporting various communication protocols and featuring low power consumption, it is extensively used in a variety of IoT applications.</p><p><strong>1.1.2 Port Layout</strong></p><img loading="lazy" height="511" width="599" class="common_img" src="'+i+'" style="width:500px;"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Port Name</strong></th><th style="text-align:center;"><strong>Function Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;">USB serial port</td><td style="text-align:center;">Used for serial communication and firmware flashing</td></tr><tr><td style="text-align:center;">Custom button</td><td style="text-align:center;">Customize the button event in the code</td></tr><tr><td style="text-align:center;">IIC port</td><td style="text-align:center;">It is the port for performing secondary development and connecting with the main controller.</td></tr></tbody></table><p><strong>1.1.3 Notice</strong></p><p>Please ensure that the module input power is at least 5V 2A, otherwise, the image may display watermarks.</p><p>The module comes with the firmware, which supports camera feedback functionality. If the vision recognition features are required, you need to flash the corresponding firmware</p><p><strong>1.1.4 Specific Technical Parameters</strong></p><p>For the detailed information, please refer to the EPS32-S3 technical parameters in <a href="./Appendix.html">Chip Materials &amp; Technical Parameters</a>.</p><h2 id="_1-2-packing-list" tabindex="-1">1.2 Packing List <a class="header-anchor" href="#_1-2-packing-list" aria-label="Permalink to &quot;1.2 Packing List&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>No.</strong></th><th style="text-align:center;"><strong>Components</strong></th><th style="text-align:center;"><strong>Quantity</strong></th><th style="text-align:center;"><strong>Picture</strong></th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">ESP32-S3 Vision Module</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="962" width="1402" src="'+r+'" style="width:250px;"></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:center;">USB Cable</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="720" width="1634" src="'+s+'" style="width:250px;"></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:center;">4PIN Wire</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="37" width="411" src="'+l+'" style="width:250px;"></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:center;">user manual</td><td style="text-align:center;">1</td><td style="text-align:center;"><img loading="lazy" height="1014" width="711" src="'+c+'" style="width:300px;"></td></tr></tbody></table><h2 id="_1-3-getting-started" tabindex="-1">1.3 Getting Started <a class="header-anchor" href="#_1-3-getting-started" aria-label="Permalink to &quot;1.3 Getting Started&quot;">​</a></h2><p><strong>1.3.1 Reminder</strong></p><p>(1) Please ensure that the module input power has a rated current greater than 2A. Otherwise, the image may display watermarks.</p><p>(2) The robot has pre-flashed firmware for video transmission functions, allowing users to quickly experience it. If other functionalities are required, different firmware will need to be flashed.</p><p><strong>1.3.2 Device Connection</strong></p><p>(1) Using a Type-C cable to connect the visual module to your computer. (Check in the Device Manager to ensure the port is connected properly)</p><img loading="lazy" height="465" width="687" class="common_img" src="'+d+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>If the device cannot be found in the port, it may be because the computer does not have the necessary drivers installed. You can find the installation package in the path <a href="./Appendix.html">Appendix-&gt;ch34xdriver (Window environment)</a> and install it.</p></div><p>(2) Connect to the hotspot generated by the module: HW_ESP32S3CAM.</p><p class="common_img" style="text-align:center;"><img loading="lazy" height="138" width="356" src="'+p+'"><img loading="lazy" height="137" width="360" src="'+g+'"></p><p>The above connection procedure is for AP direct connection mode. The visual module also supports STA local network mode. For information and operational steps related to these modes, refer to &quot;<a href="./.html"><strong>Extended Lesson</strong></a>&quot;.</p><p><strong>1.3.3 Real-time Video Transmission Implementation</strong></p><p>After typing &quot;<strong>192.168.5.1</strong>&quot; in the browser&#39;s address bar, press Enter and click <img loading="lazy" height="28" width="113" src="'+h+'"> in the opened page to access the live feed camera interface.</p><img loading="lazy" height="794" width="1346" src="'+m+'">',29)])])}const b=e(u,[["render",y]]);export{_ as __pageData,b as default};
